window.irParaNacao = function (e, t) {
    if (!e.target.closest(".admin-card-controls")) {
        window.location.href = `nacao.html?id=${t}`;
    }
};

const higienizarCaminho = (idInput) => {
    const input = document.getElementById(idInput);
    if (input) {
        input.addEventListener("input", function () {
            let valor = this.value.replace(/"/g, "").replace(/\\/g, "/");
            const indexAjuste = valor.indexOf("WT - Artes");
            if (indexAjuste !== -1) {
                valor = valor.substring(indexAjuste);
            }
            this.value = valor;
        });
    }
};

const formatarTextoTatico = (texto) => {
    if (!texto) return "";
    return texto.replace(/\*\*(.*?)\*\*/g, '<strong style="color: #F2B400;">$1</strong>').replace(/\n/g, "<br>");
};

