function ativarAbaTatica() {
    const navbar = document.querySelector(".top-navbar");
    const btn = document.getElementById("navPullTab");
    const icone = document.getElementById("pullTabIcon");

    if (navbar && btn) {
        document.body.style.paddingTop = navbar.offsetHeight + "px";
        btn.addEventListener("click", () => {
            navbar.classList.toggle("collapsed");
            if (navbar.classList.contains("collapsed")) {
                icone.textContent = "keyboard_double_arrow_down";
                document.body.style.paddingTop = "30px";
            } else {
                icone.textContent = "keyboard_double_arrow_up";
                document.body.style.paddingTop = navbar.offsetHeight + "px";
            }
        });
    }
}

function ativarRadarPesquisa(basePath) {
    const input = document.getElementById("searchInput");
    if (!input) return;

    const caixaResultados = document.createElement("div");
    let timerBusca;

    caixaResultados.id = "radarResultados";
    caixaResultados.className = "search-suggestions";
    input.parentElement.style.position = "relative";
    input.parentElement.appendChild(caixaResultados);

    input.addEventListener("input", (e) => {
        const termo = e.target.value.trim();
        clearTimeout(timerBusca);

        if (termo.length < 2) {
            caixaResultados.style.display = "none";
            return;
        }

        timerBusca = setTimeout(async () => {
            try {
                const req = await fetch(`${basePath}php/api/busca_veiculos.php?q=${encodeURIComponent(termo)}`);
                const res = await req.json();

                if (res.status === "success" && res.resultados.length > 0) {
                    caixaResultados.innerHTML = "";
                    res.resultados.forEach(tanque => {
                        caixaResultados.innerHTML += `
                            <a href="${basePath}ficha.html?id=${tanque.id}" class="suggestion-link" style="padding: 12px; border-bottom: 1px solid #333; transition: background 0.2s;" onmouseover="this.style.background='#222'" onmouseout="this.style.background='transparent'">
                                <img src="${basePath}${tanque.caminho_imagem}?v=${new Date().getTime()}" alt="${tanque.nome}" class="suggestion-icon" onerror="this.src='${basePath}WT - Artes/WT-ICO2.ico'">
                                <div style="display: flex; flex-direction: column;">
                                    <span style="font-weight: bold; font-size: 13px; color: #F2B400;">${tanque.nome}</span>
                                    <span style="font-size: 10px; color: #aaa;">${tanque.classe_veiculo || "Tanque"} | ${tanque.nivel || "?"}</span>
                                </div>
                            </a>
                        `;
                    });
                    caixaResultados.style.display = "block";
                } else {
                    caixaResultados.innerHTML = '<div style="padding: 15px; color: #ff4d4d; font-size: 12px; text-align: center; font-family: monospace;">Nenhum alvo detetado.</div>';
                    caixaResultados.style.display = "block";
                }
            } catch (err) {
                console.error("Erro na busca do radar:", err);
            }
        }, 300);
    });

    document.addEventListener("click", e => {
        if (!input.contains(e.target) && !caixaResultados.contains(e.target)) {
            caixaResultados.style.display = "none";
        }
    });
}

function iniciarRelogio() {
    let hh = document.getElementById("warHours"),
        mm = document.getElementById("warMinutes"),
        ss = document.getElementById("warSeconds"),
        dd = document.getElementById("warClockDate");

    if (!(hh && mm && ss && dd)) return;

    const meses = ["JAN", "FEV", "MAR", "ABR", "MAI", "JUN", "JUL", "AGO", "SET", "OUT", "NOV", "DEZ"];

    const atualizar = () => {
        let hoje = new Date();
        hh.textContent = String(hoje.getHours()).padStart(2, "0");
        mm.textContent = String(hoje.getMinutes()).padStart(2, "0");
        ss.textContent = String(hoje.getSeconds()).padStart(2, "0");
        dd.textContent = `${String(hoje.getDate()).padStart(2, "0")} ${meses[hoje.getMonth()]} ${hoje.getFullYear()}`;
    };

    atualizar();
    setInterval(atualizar, 1000);
}

function renderizarPlacaNacaoTopo(siglaNacao) {
    const badge = document.getElementById("userNationBadge");
    const config = NACOES_CONFIG[siglaNacao] || NACOES_CONFIG.USA;

    if (badge) {
        badge.style.borderColor = config.corBorda;
        badge.style.boxShadow = `0 0 10px ${config.glow}`;
        badge.innerHTML = `
            <div style="display:flex;align-items:center;gap:6px;">
                ${config.svg}
                <span style="font-weight:bold;color:#fff;font-size:11px;">${config.sigla}</span>
            </div>
            <span style="font-size:9px;color:#aaa;">${config.nome}</span>
            <span style="font-size:8px;color:#F2B400;margin-left:2px;">▼</span>
        `;
    }
}

function iniciarLogin(basePath) {
    let modalLogin = document.getElementById("loginModal");
    let btnNavLogin = document.querySelector(".btn-login"); // O botão na navbar
    let btnFecharModal = document.getElementById("closeModal");
    let formLogin = document.getElementById("loginForm");

    // CORREÇÃO DOS LINKS INTERNOS
    let btnIrReg = document.getElementById("linkIrParaRegistro");
    if (btnIrReg) {
        btnIrReg.addEventListener("click", (e) => {
            e.preventDefault();
            modalLogin.classList.remove("ativo");
            document.getElementById("registerModal").classList.add("ativo");
        });
    }

    let btnRadarLog = document.getElementById("btnRadar");
    let iconRadarLog = document.getElementById("radarIcon");
    let inputSenhaLog = document.getElementById("userPassword");

    if (btnRadarLog) {
        btnRadarLog.addEventListener("click", () => {
            if (inputSenhaLog.type === "password") {
                inputSenhaLog.type = "text";
                iconRadarLog.src = `${basePath}WT - Artes/UI-UX icons/Radar-ver.webp`;
            } else {
                inputSenhaLog.type = "password";
                iconRadarLog.src = `${basePath}WT - Artes/UI-UX icons/Radar-ocultar.webp`;
            }
        });
    }

    if (!modalLogin || !formLogin) return;

    let inputEmail = document.getElementById("userEmail");
    let btnSubmit = document.getElementById("btnSubmitLogin");

    window.atualizarControlesInterface = function (isAuth, role) {
        const isAdmin = isAuth && (role || "").toLowerCase() === "admin";
        document.querySelectorAll(".admin-controls").forEach(el => el.style.display = isAdmin ? "flex" : "none");

        const badgeContainer = document.getElementById("userNationBadgeContainer");
        if (badgeContainer) {
            badgeContainer.style.display = isAuth ? "flex" : "none";
            if (isAuth) renderizarPlacaNacaoTopo(localStorage.getItem("userNation") || "USA");
        }
    };

    const validarInputs = () => {
        let formValido = inputEmail.value.includes("@") && inputSenhaLog.value.length > 0;
        btnSubmit.disabled = !formValido;
        btnSubmit.classList.toggle("valido", formValido);
    };

    if (btnNavLogin) {
        btnNavLogin.addEventListener("click", (e) => {
            e.preventDefault();
            // A MAGIA ACONTECE AQUI: Se logado, abre o perfil. Se não, abre o login.
            if (localStorage.getItem("isAuth") === "true") {
                document.getElementById("profileModal").classList.add("ativo");
                // Dispara o carregamento dos dados do perfil
                if (window.carregarDadosPerfil) window.carregarDadosPerfil();
            } else {
                modalLogin.classList.add("ativo");
            }
        });
    }

    if (btnFecharModal) btnFecharModal.addEventListener("click", () => modalLogin.classList.remove("ativo"));
    inputEmail.addEventListener("input", validarInputs);
    inputSenhaLog.addEventListener("input", validarInputs);

    formLogin.addEventListener("submit", async (e) => {
        e.preventDefault();
        btnSubmit.disabled = true;
        btnSubmit.innerHTML = "AUTENTICANDO...";

        try {
            let dadosForm = new FormData();
            dadosForm.append("email", inputEmail.value);
            dadosForm.append("senha", inputSenhaLog.value);

            const req = await fetch(`${basePath}php/api/auth.php`, { method: "POST", body: dadosForm });
            const res = await req.json();
            const feedback = document.getElementById("loginFeedback");

            if (req.ok && res.status === "success") {
                localStorage.setItem("isAuth", "true");
                localStorage.setItem("userRole", res.perfil);
                localStorage.setItem("userNickname", res.nickname);
                localStorage.setItem("userNation", res.nacao_favorita || "USA");
                localStorage.setItem("csrf_token", res.csrf_token);
                window.location.reload();

            } else if (res.status === "blocked") {
                feedback.style.display = "block";
                feedback.innerHTML = `Tentativas incorretas. Tente novamente em <span id="spanMinutos">${res.minutos_restantes}</span> minuto(s).`;
                btnSubmit.innerHTML = "ACESSO BLOQUEADO";
                btnSubmit.style.backgroundColor = "#555";

                if (window.timerBloqueioLogin) clearInterval(window.timerBloqueioLogin);
                let min = res.minutos_restantes;
                window.timerBloqueioLogin = setInterval(() => {
                    min--;
                    if (min <= 0) {
                        clearInterval(window.timerBloqueioLogin);
                        feedback.style.display = "none";
                        btnSubmit.innerHTML = "AUTENTICAR";
                        btnSubmit.style.backgroundColor = "";
                        btnSubmit.disabled = false;
                    } else {
                        document.getElementById("spanMinutos").textContent = min;
                    }
                }, 60000);

            } else {
                feedback.textContent = res.message;
                feedback.style.display = "block";
                btnSubmit.innerHTML = "FALHA";
                setTimeout(() => {
                    btnSubmit.innerHTML = "AUTENTICAR";
                    btnSubmit.disabled = false;
                }, 2000);
            }
        } catch (err) {
            btnSubmit.innerHTML = "AUTENTICAR";
            btnSubmit.disabled = false;
        }
    });

    (function () {
        let isAuth = localStorage.getItem("isAuth") === "true";
        let userRole = localStorage.getItem("userRole") || "visitante";
        let textLogin = document.getElementById("navLoginText");

        if (textLogin) {
            textLogin.textContent = isAuth ? "PERFIL" : "ENTRAR"; // <-- MUDA DE "SAIR" PARA "PERFIL"
        }
        atualizarControlesInterface(isAuth, userRole);

        // Corrige o link de voltar do Registro para o Login
        let linkIrLog = document.getElementById("linkIrParaLogin");
        if (linkIrLog) {
            linkIrLog.onclick = (e) => {
                e.preventDefault();
                document.getElementById("registerModal").classList.remove("ativo");
                document.getElementById("loginModal").classList.add("ativo");
            };
        }
    })();
}

function iniciarRegistro(basePath) {
    let intlInstance;
    const modalReg = document.getElementById("registerModal");
    const btnFecharReg = document.getElementById("closeRegisterModal");
    const formReg = document.getElementById("registerForm");

    if (!modalReg || !formReg) return;

    const inNome = document.getElementById("regNome");
    const inSobrenome = document.getElementById("regSobrenome");
    const inNick = document.getElementById("regNickname");
    const inEmail = document.getElementById("regEmail");
    const inSenha = document.getElementById("regSenha");
    const inConf = document.getElementById("regConfirmar");
    const msgErroS = document.getElementById("regErroSenha");
    const msgFeed = document.getElementById("registerFeedback");
    const btnSubmit = document.getElementById("btnSubmitRegister");
    const btnRadar = document.getElementById("btnRadarReg");
    const iconRadar = document.getElementById("radarIconReg");
    const inTel = document.getElementById("regTelefone");

    if (window.intlTelInput && inTel) {
        intlInstance = window.intlTelInput(inTel, {
            initialCountry: "br",
            utilsScript: "https://cdn.jsdelivr.net/npm/intl-tel-input@23.0.10/build/js/utils.js"
        });
    }

    if (btnRadar) {
        btnRadar.addEventListener("click", () => {
            if (inSenha.type === "password") {
                inSenha.type = "text";
                iconRadar.src = `${basePath}WT - Artes/UI-UX icons/Radar-ver.webp`;
            } else {
                inSenha.type = "password";
                iconRadar.src = `${basePath}WT - Artes/UI-UX icons/Radar-ocultar.webp`;
            }
        });
    }

    const resetErros = () => {
        if (msgErroS) msgErroS.style.display = "none";
        if (msgFeed) msgFeed.style.display = "none";
    };

    const checarBotoes = () => {
        let ok = inNome.value.trim().length > 0 &&
            inSobrenome.value.trim().length > 0 &&
            inNick.value.trim().length > 0 &&
            inEmail.value.includes("@") &&
            inSenha.value.length > 0 &&
            inConf.value.length > 0;

        btnSubmit.disabled = !ok;
        btnSubmit.classList.toggle("valido", ok);
    };

    [inNome, inSobrenome, inNick, inEmail, inSenha, inConf].forEach(el => {
        el.addEventListener("input", () => { resetErros(); checarBotoes(); });
    });

    if (btnFecharReg) {
        btnFecharReg.addEventListener("click", () => {
            modalReg.classList.remove("ativo");
            formReg.reset();
            resetErros();
            checarBotoes();
        });
    }

    formReg.addEventListener("submit", async (e) => {
        e.preventDefault();
        resetErros();

        if (inSenha.value !== inConf.value) {
            msgErroS.textContent = "AS CHAVES CRIPTOGRÁFICAS NÃO COINCIDEM.";
            msgErroS.style.display = "block";
            return;
        }

        const pwd = inSenha.value;
        if (pwd.length < 8) {
            msgErroS.textContent = "A CHAVE DEVE TER NO MÍNIMO 8 CARACTERES.";
            msgErroS.style.display = "block"; return;
        }
        if (!/[A-Z]/.test(pwd) || !/[a-z]/.test(pwd)) {
            msgErroS.textContent = "A CHAVE DEVE CONTER LETRAS MAIÚSCULAS E MINÚSCULAS.";
            msgErroS.style.display = "block"; return;
        }
        if (!/\d/.test(pwd)) {
            msgErroS.textContent = "A CHAVE DEVE CONTER AO MENOS UM NÚMERO (0-9).";
            msgErroS.style.display = "block"; return;
        }
        if (!/[\W_]/.test(pwd)) {
            msgErroS.textContent = "A CHAVE DEVE CONTER AO MENOS UM SÍMBOLO ESPECIAL (!@#$%&*...).";
            msgErroS.style.display = "block"; return;
        }

        const dominio = inEmail.value.trim().toLowerCase().split("@")[1] || "";
        if (dominio === "wtwiki.com") {
            msgFeed.textContent = "ACESSO NEGADO: O domínio @wtwiki.com é restrito ao Alto Comando.";
            msgFeed.style.display = "block"; return;
        }

        const dominiosSuspeitos = ["gamil.com", "gmaill.com", "gmai.com", "gmail.com.br", "gmeil.com", "hotmial.com", "hotmai.com", "outlok.com", "yaho.com"];
        if (dominiosSuspeitos.includes(dominio)) {
            msgFeed.textContent = `DOMÍNIO SUSPEITO: Você digitou @${dominio}. Corrija para um provedor válido.`;
            msgFeed.style.display = "block"; return;
        }

        btnSubmit.disabled = true;
        btnSubmit.classList.remove("valido");
        let htmlAntigo = btnSubmit.innerHTML;
        btnSubmit.innerHTML = `<img src="${basePath}WT - Artes/UI-UX icons/Loading-icon.webp" alt="" style="width:24px;animation:spin 1s linear infinite;"> PROCESSANDO...`;

        try {
            let dados = new FormData();
            dados.append("nome", inNome.value);
            dados.append("sobrenome", inSobrenome.value);
            dados.append("nickname", inNick.value);
            dados.append("email", inEmail.value);
            dados.append("email_contato", document.getElementById("regEmailContato").value);
            dados.append("telefone", intlInstance ? intlInstance.getNumber() : inTel.value);
            dados.append("senha", inSenha.value);

            const req = await fetch(`${basePath}php/api/register.php`, { method: "POST", body: dados });
            const texto = await req.text();
            let jsonResposta;

            try {
                jsonResposta = JSON.parse(texto);
            } catch (err) {
                console.error("Resposta Inválida do Servidor:", texto);
                throw new Error("Erro interno do servidor.");
            }

            if (req.ok && jsonResposta.status === "success") {
                btnSubmit.innerHTML = "ALISTAMENTO CONCLUÍDO!";
                btnSubmit.style.backgroundColor = "#4caf50";

                let banner = document.getElementById("customBanner");
                if (banner) {
                    document.getElementById("customBannerText").textContent = "Soldado registrado! Proceda com a autenticação.";
                    banner.classList.add("show");
                    setTimeout(() => banner.classList.remove("show"), 5000);
                }

                setTimeout(() => {
                    modalReg.classList.remove("ativo");
                    formReg.reset();
                    btnSubmit.innerHTML = htmlAntigo;
                    btnSubmit.style.backgroundColor = "";
                    checarBotoes();
                    document.getElementById("loginModal").classList.add("ativo");
                }, 2000);
            } else {
                if (msgFeed) {
                    msgFeed.textContent = jsonResposta.message;
                    msgFeed.style.display = "block";
                }
                btnSubmit.innerHTML = htmlAntigo;
                checarBotoes();
            }
        } catch (err) {
            if (msgFeed) {
                msgFeed.textContent = err.message;
                msgFeed.style.display = "block";
            }
            btnSubmit.innerHTML = htmlAntigo;
            checarBotoes();
        }
    });
}

function iniciarPerfil(basePath) {
    const modal = document.getElementById("profileModal");
    if (!modal) return;

    const btnClose = document.getElementById("closeProfileModal");
    const btnLogout = document.getElementById("btnLogout");
    const feedback = document.getElementById("profileFeedback");

    // Tabs
    const tabDados = document.getElementById("tabDados");
    const tabSenha = document.getElementById("tabSenha");
    const formDados = document.getElementById("formPerfilDados");
    const formSenha = document.getElementById("formPerfilSenha");

    btnClose.addEventListener("click", () => modal.classList.remove("ativo"));

    tabDados.addEventListener("click", () => {
        tabDados.style.background = "#F2B400"; tabDados.style.color = "#000";
        tabSenha.style.background = "#333"; tabSenha.style.color = "#fff";
        formDados.style.display = "block"; formSenha.style.display = "none";
        feedback.style.display = "none";
    });

    tabSenha.addEventListener("click", () => {
        tabSenha.style.background = "#F2B400"; tabSenha.style.color = "#000";
        tabDados.style.background = "#333"; tabDados.style.color = "#fff";
        formSenha.style.display = "block"; formDados.style.display = "none";
        feedback.style.display = "none";
    });

    // Função exposta para carregar dados ao abrir
    window.carregarDadosPerfil = async () => {
        try {
            const req = await fetch(`${basePath}php/api/perfil.php?acao=get`);
            const res = await req.json();
            if (res.status === "success") {
                document.getElementById("perfilNick").value = res.dados.nickname;
                document.getElementById("perfilNome").value = res.dados.nome;
                document.getElementById("perfilSobrenome").value = res.dados.sobrenome;
                document.getElementById("perfilEmailContato").value = res.dados.email_contato || "";
                document.getElementById("perfilTelefone").value = res.dados.telefone || "";
            }
        } catch (e) { console.error("Erro ao carregar perfil."); }
    };

    // Salvar Dados
    formDados.addEventListener("submit", async (e) => {
        e.preventDefault();
        const btn = document.getElementById("btnSalvarPerfil");
        btn.disabled = true; btn.innerHTML = "SALVANDO...";

        let fd = new FormData();
        fd.append("acao", "update_dados");
        fd.append("nome", document.getElementById("perfilNome").value);
        fd.append("sobrenome", document.getElementById("perfilSobrenome").value);
        fd.append("email_contato", document.getElementById("perfilEmailContato").value);
        fd.append("telefone", document.getElementById("perfilTelefone").value);
        fd.append("senha_atual", document.getElementById("perfilSenhaAtualDados").value);
        fd.append("csrf_token", localStorage.getItem("csrf_token") || "");

        try {
            const req = await fetch(`${basePath}php/api/perfil.php`, { method: "POST", body: fd });
            const res = await req.json();
            feedback.style.display = "block";
            feedback.style.borderLeft = res.status === "success" ? "4px solid #4caf50" : "4px solid var(--rus-vermelho)";
            feedback.style.background = res.status === "success" ? "#122a18" : "#2a1212";
            feedback.style.color = res.status === "success" ? "#80ff9f" : "#ff8080";
            feedback.textContent = res.message;
            if (res.status === "success") document.getElementById("perfilSenhaAtualDados").value = "";
        } catch (err) {
            feedback.textContent = "Erro de conexão.";
            feedback.style.display = "block";
        }
        btn.disabled = false; btn.innerHTML = "ATUALIZAR REGISTROS";
    });

    // Mudar Senha
    formSenha.addEventListener("submit", async (e) => {
        e.preventDefault();
        const n1 = document.getElementById("perfilNovaSenha").value;
        const n2 = document.getElementById("perfilConfirmarSenha").value;

        if (n1 !== n2) {
            feedback.style.display = "block";
            feedback.style.borderLeft = "4px solid var(--rus-vermelho)";
            feedback.style.background = "#2a1212"; feedback.style.color = "#ff8080";
            feedback.textContent = "As novas senhas não coincidem."; return;
        }

        const btn = document.getElementById("btnSalvarNovaSenha");
        btn.disabled = true; btn.innerHTML = "PROCESSANDO...";

        let fd = new FormData();
        fd.append("acao", "update_senha");
        fd.append("senha_atual", document.getElementById("perfilSenhaAtual").value);
        fd.append("nova_senha", n1);
        fd.append("csrf_token", localStorage.getItem("csrf_token") || "");

        try {
            const req = await fetch(`${basePath}php/api/perfil.php`, { method: "POST", body: fd });
            const res = await req.json();
            feedback.style.display = "block";
            feedback.style.borderLeft = res.status === "success" ? "4px solid #4caf50" : "4px solid var(--rus-vermelho)";
            feedback.style.background = res.status === "success" ? "#122a18" : "#2a1212";
            feedback.style.color = res.status === "success" ? "#80ff9f" : "#ff8080";
            feedback.textContent = res.message;
            if (res.status === "success") formSenha.reset();
        } catch (err) {
            feedback.textContent = "Erro de conexão.";
            feedback.style.display = "block";
        }
        btn.disabled = false; btn.innerHTML = "ALTERAR CREDENCIAL";
    });

    // Logout Centralizado
    btnLogout.addEventListener("click", async () => {
        try {
            await fetch(`${basePath}php/api/logout.php`);
            localStorage.clear();
            window.location.reload();
        } catch (err) { }
    });
}

function iniciarRecuperacaoSenha(basePath) {
    const btnEsqueci = document.getElementById("esqueciSenhaBtn");
    const modalRec = document.getElementById("recoverModal");
    const btnFechar = document.getElementById("closeRecoverModal");
    const formReq = document.getElementById("recoverForm");
    const formRes = document.getElementById("resetForm");
    const msgFeed = document.getElementById("recoverFeedback");

    if (!modalRec) return;

    if (btnEsqueci) {
        btnEsqueci.addEventListener("click", (e) => {
            e.preventDefault();
            const modalLogin = document.getElementById("loginModal");
            if (modalLogin) modalLogin.classList.remove("ativo");
            modalRec.classList.add("ativo");
            if (msgFeed) msgFeed.style.display = "none";
        });
    }

    if (btnFechar) btnFechar.addEventListener("click", () => modalRec.classList.remove("ativo"));

    if (formReq) {
        formReq.addEventListener("submit", async (e) => {
            e.preventDefault();
            const btn = document.getElementById("btnSubmitRecover");
            const htmlVelho = btn.innerHTML;
            btn.disabled = true;
            btn.innerHTML = `<img src="${basePath}WT - Artes/UI-UX icons/Loading-icon.webp" alt="" style="width:20px;height:auto;vertical-align:middle;animation:spin 1s linear infinite;"> LOCALIZANDO...`;
            btn.style.backgroundColor = "#F2B400";

            try {
                let dados = new FormData();
                dados.append("email", document.getElementById("recoverEmail").value);
                const req = await fetch(`${basePath}php/api/recover.php`, { method: "POST", body: dados });
                const res = await req.json();

                if (msgFeed) {
                    msgFeed.style.display = "block";
                    msgFeed.style.borderLeftColor = res.status === "success" ? "#4caf50" : "var(--rus-vermelho)";
                    msgFeed.style.background = res.status === "success" ? "#122a18" : "#2a1212";
                    msgFeed.style.color = res.status === "success" ? "#80ff9f" : "#ff8080";
                    msgFeed.textContent = res.message;
                }

                if (res.status === "success") {
                    formReq.style.display = "none";
                    formRes.style.display = "block";
                    if (res.token_teste) {
                        document.getElementById("resetToken").value = res.token_teste;
                    }
                }
            } catch (err) {
                if (msgFeed) {
                    msgFeed.style.display = "block";
                    msgFeed.textContent = "Falha ao contactar a central de recuperação.";
                }
            } finally {
                btn.innerHTML = htmlVelho;
                btn.style.backgroundColor = "";
                btn.disabled = false;
            }
        });
    }

    if (formRes) {
        formRes.addEventListener("submit", async (e) => {
            e.preventDefault();
            const btn = document.getElementById("btnSubmitReset");
            const htmlVelho = btn.innerHTML;
            btn.disabled = true;
            btn.innerHTML = `<img src="${basePath}WT - Artes/UI-UX icons/Loading-icon.webp" alt="" style="width:20px;height:auto;vertical-align:middle;animation:spin 1s linear infinite;"> REDEFININDO...`;
            btn.style.backgroundColor = "#F2B400";

            try {
                let dados = new FormData();
                dados.append("token", document.getElementById("resetToken").value);
                dados.append("nova_senha", document.getElementById("resetSenha").value);

                const req = await fetch(`${basePath}php/api/reset_password.php`, { method: "POST", body: dados });
                const res = await req.json();

                if (msgFeed) {
                    msgFeed.style.display = "block";
                    msgFeed.textContent = res.message;
                }

                if (res.status === "success") {
                    setTimeout(() => {
                        modalRec.classList.remove("ativo");
                        formRes.reset();
                        formReq.reset();
                        formReq.style.display = "block";
                        formRes.style.display = "none";
                        const modalLogin = document.getElementById("loginModal");
                        if (modalLogin) modalLogin.classList.add("ativo");
                    }, 1800);
                }
            } catch (err) {
                if (msgFeed) {
                    msgFeed.style.display = "block";
                    msgFeed.textContent = "Erro ao redefinir a credencial.";
                }
            } finally {
                btn.innerHTML = htmlVelho;
                btn.style.backgroundColor = "";
                btn.disabled = false;
            }
        });
    }
}

function iniciarTropas(basePath) {
    const modal = document.getElementById("tropasModal");
    const btnOpen = document.getElementById("btnOpenTropas");
    const btnClose = document.getElementById("closeTropasModal");
    const tbody = document.getElementById("listaSoldadosTbody");
    const feedback = document.getElementById("tropasFeedback");
    
    const inputBusca = document.getElementById("buscaSoldadoInput");
    const selectOrdem = document.getElementById("ordenaSoldadosSelect");
    const selectNacao = document.getElementById("filtroNacaoSelect");

    let todosSoldados = [];

    if (!modal || !btnOpen) return;

    btnOpen.addEventListener("click", (e) => {
        e.preventDefault();
        modal.classList.add("ativo");
        carregarTropas();
    });

    if (btnClose) btnClose.addEventListener("click", () => modal.classList.remove("ativo"));

    async function carregarTropas() {
        tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; padding: 20px;">Sincronizando dossiês com o Comando Central...</td></tr>';
        try {
            const req = await fetch(`${basePath}php/api/tropas.php?acao=listar`);
            const res = await req.json();

            if (res.status === "success") {
                todosSoldados = res.dados;
                renderizarTabela();
            } else {
                tbody.innerHTML = `<tr><td colspan="6" style="text-align: center; color: var(--rus-vermelho); padding: 20px;">${res.message}</td></tr>`;
            }
        } catch (err) {
            tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; color: var(--rus-vermelho); padding: 20px;">Falha ao sincronizar dados com o servidor (Verifique a API).</td></tr>';
        }
    }

    // Motor de Busca e Filtros em Tempo Real
    function renderizarTabela() {
        let filtrados = todosSoldados.filter(s => {
            let textoBusca = inputBusca.value.toLowerCase();
            let matchBusca = s.nickname.toLowerCase().includes(textoBusca) || s.email.toLowerCase().includes(textoBusca);
            let matchNacao = selectNacao.value === "TODAS" || s.nacao_favorita === selectNacao.value;
            return matchBusca && matchNacao;
        });

        // Lógica de Ordenação
        filtrados.sort((a, b) => {
            if (selectOrdem.value === "recente") return b.id - a.id;
            if (selectOrdem.value === "antigo") return a.id - b.id;
            if (selectOrdem.value === "az") return a.nickname.localeCompare(b.nickname);
            if (selectOrdem.value === "za") return b.nickname.localeCompare(a.nickname);
            return 0;
        });

        tbody.innerHTML = "";
        if (filtrados.length === 0) {
            tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; padding: 20px; color:#aaa;">Nenhum soldado encontrado nestas coordenadas.</td></tr>';
            return;
        }

        filtrados.forEach(user => {
            let badgeClass = user.perfil === 'admin' ? 'background:#F2B400;color:#000;' : 'background:#333;color:#fff;';
            let statusColor = user.status === 'ativo' ? '#4caf50' : '#ff4d4d';
            let btnAcao = user.status === 'ativo' ? 'SUSPENDER' : 'REATIVAR';
            let btnBg = user.status === 'ativo' ? 'var(--rus-vermelho)' : '#4caf50';
            
            tbody.innerHTML += `
                <tr style="border-bottom: 1px solid #222;">
                    <td style="padding: 10px 8px; font-weight:bold; color:#fff;">${user.nickname}</td>
                    <td style="padding: 10px 8px; color:#aaa;">${user.email}</td>
                    <td style="padding: 10px 8px;"><span style="background:#111; border:1px solid #444; padding:2px 6px; border-radius:3px;">${user.nacao_favorita || 'USA'}</span></td>
                    <td style="padding: 10px 8px;"><span style="${badgeClass} padding:2px 6px; border-radius:3px; font-size:10px; font-weight:bold;">${user.perfil.toUpperCase()}</span></td>
                    <td style="padding: 10px 8px; color:${statusColor}; font-weight:bold;">${user.status.toUpperCase()}</td>
                    <td style="padding: 10px 8px; text-align:center;">
                        <button class="btn-submit-militar" style="padding:6px; font-size:10px; width:auto; margin:0; background:${btnBg}; color:#fff;" onclick="window.alterarStatusTropa(${user.id}, '${user.status === 'ativo' ? 'suspenso' : 'ativo'}')">
                            ${btnAcao}
                        </button>
                    </td>
                </tr>
            `;
        });
    }

    if (inputBusca) inputBusca.addEventListener("input", renderizarTabela);
    if (selectOrdem) selectOrdem.addEventListener("change", renderizarTabela);
    if (selectNacao) selectNacao.addEventListener("change", renderizarTabela);

    // Função de Exclusão Lógica (Suspensão)
    window.alterarStatusTropa = async (id, novoStatus) => {
        if(!confirm(`Confirma a alteração de status para ${novoStatus.toUpperCase()}?`)) return;
        
        let fd = new FormData();
        fd.append("acao", "alterar_status");
        fd.append("id_usuario", id);
        fd.append("status", novoStatus);
        
        try {
            const req = await fetch(`${basePath}php/api/tropas.php`, { method: "POST", body: fd });
            const res = await req.json();
            
            feedback.style.display = "block";
            feedback.style.borderLeft = res.status === "success" ? "4px solid #4caf50" : "4px solid var(--rus-vermelho)";
            feedback.style.background = res.status === "success" ? "#122a18" : "#2a1212";
            feedback.style.color = res.status === "success" ? "#80ff9f" : "#ff8080";
            feedback.textContent = res.message;

            if(res.status === "success") carregarTropas();
            
        } catch(e) {
            feedback.style.display = "block";
            feedback.textContent = "Erro de comunicação com o comando central.";
        }
        
        setTimeout(() => feedback.style.display = "none", 4000);
    };
}

function iniciarIndex(basePath) {
    const carrossel = document.getElementById("nacoesCarrossel");
    if (!carrossel) return;

    const btnNova = document.getElementById("btnNovaNacao");
    const modalNacao = document.getElementById("modalGerenciarNacao");
    const btnCancela = document.getElementById("btnCancelarEdicao");
    const btnFechaX = document.getElementById("closeNacaoModalX");
    const roleUser = (localStorage.getItem("userRole") || "").toLowerCase();

    let nacoesCacheadas = [];

    const bindBotoesAdmin = () => {
        document.querySelectorAll(".btn-editar-nacao").forEach(btn => {
            btn.addEventListener("click", e => {
                const nId = e.currentTarget.getAttribute("data-id");
                const obj = nacoesCacheadas.find(x => x.Id == nId);

                document.getElementById("nacaoId").value = obj.Id;
                document.getElementById("nacaoNome").value = obj.nome;
                document.getElementById("nacaoCor").value = obj.cor_hex;
                document.getElementById("nacaoBandeira").value = obj.caminho_bandeira || "";
                document.getElementById("nacaoSilhueta").value = obj.icone_silhueta || "";
                document.getElementById("nacaoResumo").value = obj.resumo_card || "";
                document.getElementById("tituloModalNacao").textContent = "EDITAR DADOS DA NAÇÃO";
                modalNacao.classList.add("ativo");
            });
        });

        document.querySelectorAll(".btn-excluir-nacao").forEach(btn => {
            btn.addEventListener("click", async e => {
                const nId = e.currentTarget.getAttribute("data-id");
                const obj = nacoesCacheadas.find(x => x.Id == nId);

                if (confirm(`ALERTA SEVERO:\nDeletar a nação "${obj.nome}" destruirá todos os tanques associados a ela.\nProsseguir com a obliteração?`)) {
                    let form = new FormData();
                    form.append("acao", "excluir_nacao");
                    form.append("id", nId);
                    form.append("csrf_token", localStorage.getItem("csrf_token") || ""); // Passo 1.2

                    const req = await fetch(`${basePath}php/api/admin_index_api.php`, { method: "POST", body: form });
                    if (req.ok) window.location.reload();
                }
            });
        });
    };

    const fechar = () => modalNacao.classList.remove("ativo");
    if (btnFechaX) btnFechaX.addEventListener("click", fechar);
    if (btnCancela) btnCancela.addEventListener("click", fechar);

    if (roleUser === "admin" && btnNova) {
        btnNova.style.display = "block";
        btnNova.addEventListener("click", () => {
            document.getElementById("formGerenciarNacao").reset();
            document.getElementById("nacaoId").value = "";
            document.getElementById("tituloModalNacao").textContent = "FUNDAR NOVA NAÇÃO";
            modalNacao.classList.add("ativo");
        });

        higienizarCaminho("nacaoBandeira");
        higienizarCaminho("nacaoSilhueta");

        document.getElementById("formGerenciarNacao").addEventListener("submit", async e => {
            e.preventDefault();
            const b = document.getElementById("btnSalvarNacao");
            b.disabled = true;
            b.innerHTML = "PROCESSANDO...";

            let form = new FormData();
            form.append("acao", "salvar_nacao");
            form.append("id", document.getElementById("nacaoId").value);
            form.append("nome", document.getElementById("nacaoNome").value);
            form.append("cor", document.getElementById("nacaoCor").value);
            form.append("bandeira", document.getElementById("nacaoBandeira").value);
            form.append("silhueta", document.getElementById("nacaoSilhueta").value);
            form.append("resumo", document.getElementById("nacaoResumo").value);
            form.append("csrf_token", localStorage.getItem("csrf_token") || ""); // Passo 1.2

            try {
                const req = await fetch(`${basePath}php/api/admin_index_api.php`, { method: "POST", body: form });
                const res = await req.json();

                if (req.ok && res.status === "success") {
                    window.location.reload();
                } else {
                    alert("Erro: " + res.message);
                    b.disabled = false;
                    b.innerHTML = "SALVAR NAÇÃO";
                }
            } catch (err) {
                b.disabled = false;
                b.innerHTML = "SALVAR NAÇÃO";
            }
        });
    }

    (async () => {
        try {
            const req = await fetch(`${basePath}php/api/listar_nacoes.php`);
            const res = await req.json();
            if (res.status === "success") {
                nacoesCacheadas = res.nacoes;
                carrossel.innerHTML = "";

                if (document.getElementById("contadorNacoes")) {
                    document.getElementById("contadorNacoes").textContent = `${nacoesCacheadas.length} NAÇÕES`;
                }

                nacoesCacheadas.forEach(n => {
                    let controlesAdmin = "";
                    if (roleUser === "admin") {
                        controlesAdmin = `
                            <div class="admin-card-controls">
                                <button class="btn-admin-card btn-editar-nacao" data-id="${n.Id}" style="background: #F2B400; color: #000;"><span class="material-symbols-outlined" style="font-size: 16px;">edit</span></button>
                                <button class="btn-admin-card btn-excluir-nacao" data-id="${n.Id}" style="background: var(--rus-vermelho); color: #fff;"><span class="material-symbols-outlined" style="font-size: 16px;">delete</span></button>
                            </div>
                        `;
                    }

                    carrossel.innerHTML += `
                        <div class="nation-card nation-bg card-custom-${n.Id}" onclick="irParaNacao(event, ${n.Id})" 
                             style="background-color: #555555; background-image: url('${basePath}${n.caminho_bandeira}?v=${new Date().getTime()}'); background-size: cover; background-position: center; background-blend-mode: multiply; border-color: ${n.cor_hex};">
                            
                            ${controlesAdmin}
                            
                            <h1 class="nation-title" style="text-shadow: 2px 2px 5px #000;">${n.nome.toUpperCase()}</h1>
                            
                            <img class="tank-silhueta" src="${basePath}${n.icone_silhueta || "WT - Artes/WT-ICO2.ico"}?v=${new Date().getTime()}" alt="Silhueta de ${n.nome}" onerror="this.src='${basePath}WT - Artes/WT-ICO2.ico'">
                            
                            <div class="card-info-box" style="border-top: 2px solid ${n.cor_hex}; box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.5);">
                                <p>"${n.resumo_card || "Força Militar em estruturação."}"</p>
                            </div>
                        </div>
                    `;
                });
                bindBotoesAdmin();
            }
        } catch (err) { }
    })();
}

function iniciarNacao(basePath) {
    const container = document.getElementById("nacaoContainer");
    if (!container) return;

    const nId = new URLSearchParams(window.location.search).get("id");
    const loadOverlay = document.getElementById("loadingOverlay");
    const lista = document.getElementById("listaTanques");
    const btnEdit = document.getElementById("btnEditarNacao");
    const btnNovo = document.getElementById("btnNovoTanque");
    const modalEdit = document.getElementById("edicaoNacaoModal");
    const roleUser = (localStorage.getItem("userRole") || "").toLowerCase();

    if (!nId) {
        if (loadOverlay) loadOverlay.innerHTML = "<span style='color:red;'>Nação não identificada.</span>";
        return;
    }

    const btnCloseModal = document.getElementById("closeNacaoModal");
    if (btnCloseModal) btnCloseModal.addEventListener("click", () => modalEdit.classList.remove("ativo"));

    higienizarCaminho("editNacaoBandeira");

    const formEdit = document.getElementById("formEdicaoNacao");
    if (formEdit) {
        formEdit.addEventListener("submit", async e => {
            e.preventDefault();
            const b = document.getElementById("btnSalvarNacao");
            b.disabled = true;
            b.innerHTML = "ATUALIZANDO...";

            try {
                let form = new FormData();
                form.append("acao", "salvar_nacao");
                form.append("id", document.getElementById("editNacaoId").value);
                form.append("nome", document.getElementById("editNacaoNome").value);
                form.append("cor", document.getElementById("editNacaoCor").value);
                form.append("bandeira", document.getElementById("editNacaoBandeira").value);
                form.append("lore", document.getElementById("editNacaoLore").value);
                form.append("silhueta", document.getElementById("formEdicaoNacao").dataset.silhueta);
                form.append("resumo", document.getElementById("formEdicaoNacao").dataset.resumo);
                form.append("csrf_token", localStorage.getItem("csrf_token") || ""); // Passo 1.2

                const req = await fetch(`${basePath}php/api/admin_index_api.php`, { method: "POST", body: form });
                if (req.ok) window.location.reload();
            } catch (err) {
                b.disabled = false;
                b.innerHTML = "ERRO";
            }
        });
    }

    (async () => {
        try {
            const req = await fetch(`${basePath}php/api/listar_frota_nacao.php?nacao_id=${nId}`);
            const res = await req.json();

            if (res.status === "success") {
                const nacaoObj = res.nacao;
                const tanques = res.tanques;

                document.title = `${nacaoObj.nome.toUpperCase()} - War Thunder`;
                document.getElementById("dinNomeNacao").textContent = nacaoObj.nome.toUpperCase();
                document.getElementById("dinBandeira").src = `${basePath}${nacaoObj.caminho_bandeira || ""}?v=${new Date().getTime()}`;

                document.getElementById("bannerContainer").style.borderBottomColor = nacaoObj.cor_hex !== "#ffffff" ? nacaoObj.cor_hex : "#444";
                document.getElementById("dinLoreNacao").innerHTML = nacaoObj.lore_taticas ? formatarTextoTatico(nacaoObj.lore_taticas) : "<p class='paragraph'>Doutrina militar confidencial.</p>";

                lista.innerHTML = "";
                if (tanques.length > 0) {
                    tanques.forEach((t, i) => {
                        lista.innerHTML += `
                            <a href="${basePath}ficha.html?id=${t.id}" class="tank-card nation-bg">
                                <img src="${basePath}${t.caminho_imagem}?v=${new Date().getTime()}" alt="Silhueta" class="list-silhouette" onerror="this.src='${basePath}WT - Artes/WT-ICO2.ico'">
                                <div class="tank-info">
                                    <span class="tank-name">${i + 1}. ${t.nome}</span>
                                    <span class="tank-desc">${t.descricao_breve ? t.descricao_breve + "..." : "Pendente."}</span>
                                </div>
                            </a>
                        `;
                    });
                } else {
                    lista.innerHTML = '<div style="text-align: center; padding: 20px; color: #ff4d4d;">Nenhum veículo estacionado nesta base.</div>';
                }

                if (loadOverlay) loadOverlay.style.display = "none";
                container.style.display = "flex";

                if (roleUser === "admin") {
                    if (btnEdit) {
                        btnEdit.style.display = "flex";
                        btnEdit.onclick = () => {
                            document.getElementById("editNacaoId").value = nId;
                            document.getElementById("editNacaoNome").value = nacaoObj.nome;
                            document.getElementById("editNacaoCor").value = nacaoObj.cor_hex;
                            document.getElementById("editNacaoBandeira").value = nacaoObj.caminho_bandeira || "";
                            document.getElementById("editNacaoLore").value = nacaoObj.lore_taticas || "";
                            document.getElementById("formEdicaoNacao").dataset.silhueta = nacaoObj.icone_silhueta || "";
                            document.getElementById("formEdicaoNacao").dataset.resumo = nacaoObj.resumo_card || "";
                            modalEdit.classList.add("ativo");
                        };
                    }

                    if (btnNovo) {
                        btnNovo.style.display = "flex";
                        btnNovo.onclick = async () => {
                            if (confirm("Autorizar início de produção de um novo blindado?")) {
                                btnNovo.innerHTML = "SOLICITANDO...";
                                btnNovo.disabled = true;
                                try {
                                    let form = new FormData();
                                    form.append("acao", "novo_tanque");
                                    form.append("nacao_id", nId);
                                    form.append("csrf_token", localStorage.getItem("csrf_token") || ""); // Passo 1.2

                                    const req = await fetch(`${basePath}php/api/admin_nacao_api.php`, { method: "POST", body: form });
                                    const resp = await req.json();

                                    if (req.ok && resp.status === "success") {
                                        window.location.href = `${basePath}ficha.html?id=${resp.novo_id}`;
                                    } else {
                                        alert("Falha: " + resp.message);
                                        btnNovo.innerHTML = "TENTAR NOVAMENTE";
                                        btnNovo.disabled = false;
                                    }
                                } catch (err) {
                                    btnNovo.disabled = false;
                                }
                            }
                        };
                    }
                }
            } else {
                if (loadOverlay) loadOverlay.innerHTML = `<span style='color:red;'>${res.message}</span>`;
            }
        } catch (err) {
            if (loadOverlay) loadOverlay.innerHTML = "<span style='color:red;'>Falha de conexão.</span>";
        }
    })();
}

function iniciarFicha(basePath) {
    const containerFicha = document.getElementById("fichaContainer");
    if (!containerFicha) return;

    const tId = new URLSearchParams(window.location.search).get("id");
    const loadOverlay = document.getElementById("loadingOverlay");
    const modalEdicao = document.getElementById("edicaoTanqueModal");
    const btnAbrirEdicao = document.getElementById("btnAbrirEdicao");

    let specsState = [];
    let galeriaState = [];

    if (!tId) {
        if (loadOverlay) loadOverlay.innerHTML = "<span style='color:red;'>ERRO: Blindado não especificado.</span>";
        return;
    }

    const corClasses = {
        "Leve": "#FFD700",
        "Médio": "#FF8C00",
        "Pesado": "#DC143C",
        "Caça-Tanques": "#228B22",
        "SPAA": "#8A2BE2"
    };
    const prefixos = {
        "Leve": "Tanque Leve",
        "Médio": "Tanque Médio",
        "Pesado": "Tanque Pesado",
        "Caça-Tanques": "Caça-Tanques",
        "SPAA": "SPAA (Antiaérea)"
    };

    if (document.getElementById("closeEdicaoModal")) {
        document.getElementById("closeEdicaoModal").onclick = () => modalEdicao.classList.remove("ativo");
    }

    const resetTabs = () => {
        ["tabFichaLore", "tabGaleria"].forEach(id => {
            document.getElementById(id).style.background = "#333";
            document.getElementById(id).style.color = "#fff";
        });
        ["painelFichaLore", "painelGaleria"].forEach(id => {
            document.getElementById(id).style.display = "none";
        });
    };

    if (document.getElementById("tabFichaLore")) {
        document.getElementById("tabFichaLore").onclick = (e) => {
            resetTabs();
            e.target.style.background = "#F2B400";
            e.target.style.color = "#000";
            document.getElementById("painelFichaLore").style.display = "block";
        };
    }

    if (document.getElementById("tabGaleria")) {
        document.getElementById("tabGaleria").onclick = (e) => {
            resetTabs();
            e.target.style.background = "#F2B400";
            e.target.style.color = "#000";
            document.getElementById("painelGaleria").style.display = "block";
        };
    }

    higienizarCaminho("editCaminhoImagem");
    higienizarCaminho("novaFotoCaminho");

    const renderizarEditorAtributos = () => {
        const cx = document.getElementById("listaAtributosContainer");
        cx.innerHTML = "";
        specsState.forEach((item, index) => {
            cx.insertAdjacentHTML("beforeend", `
                <div class="attr-row">
                    <div style="display:flex; flex-direction:column; gap:2px;">
                        <button type="button" class="btn-move btn-up" data-idx="${index}">▲</button>
                        <button type="button" class="btn-move btn-down" data-idx="${index}">▼</button>
                    </div>
                    <input type="text" class="input-chave" data-idx="${index}" value="${item.chave}" style="flex: 1;" placeholder="Atributo">
                    <input type="text" class="input-valor" data-idx="${index}" value="${item.valor}" style="flex: 2;" placeholder="Valor (Vazio = oculto)">
                    <button type="button" class="btn-del-attr" data-idx="${index}" style="background:var(--rus-vermelho); color:#fff; border:none; padding:8px;">X</button>
                </div>
            `);
        });

        document.querySelectorAll(".input-chave").forEach(el => el.onchange = (e) => specsState[e.target.dataset.idx].chave = e.target.value);
        document.querySelectorAll(".input-valor").forEach(el => el.onchange = (e) => specsState[e.target.dataset.idx].valor = e.target.value);

        document.querySelectorAll(".btn-up").forEach(el => el.onclick = (e) => {
            const idx = parseInt(e.target.dataset.idx);
            if (idx > 0) {
                [specsState[idx - 1], specsState[idx]] = [specsState[idx], specsState[idx - 1]];
                renderizarEditorAtributos();
            }
        });

        document.querySelectorAll(".btn-down").forEach(el => el.onclick = (e) => {
            const idx = parseInt(e.target.dataset.idx);
            if (idx < specsState.length - 1) {
                [specsState[idx + 1], specsState[idx]] = [specsState[idx], specsState[idx + 1]];
                renderizarEditorAtributos();
            }
        });

        document.querySelectorAll(".btn-del-attr").forEach(el => el.onclick = (e) => {
            specsState.splice(parseInt(e.target.dataset.idx), 1);
            renderizarEditorAtributos();
        });
    };

    if (document.getElementById("btnInjetarTemplate")) {
        document.getElementById("btnInjetarTemplate").onclick = () => {
            ["Armamento Principal", "Blindagem do Chassi", "Blindagem da Torre", "Velocidade Máxima", "Tripulação"].forEach(k => {
                if (!specsState.some(i => i.chave === k)) specsState.push({ chave: k, valor: "" });
            });
            renderizarEditorAtributos();
        };
    }

    if (document.getElementById("btnAdicionarAtributo")) {
        document.getElementById("btnAdicionarAtributo").onclick = () => {
            const c = document.getElementById("novoAtributoChave").value.trim();
            const v = document.getElementById("novoAtributoValor").value.trim();
            if (c) {
                specsState.push({ chave: c, valor: v });
                document.getElementById("novoAtributoChave").value = "";
                document.getElementById("novoAtributoValor").value = "";
                renderizarEditorAtributos();
            }
        };
    }

    const renderizarEditorGaleria = () => {
        const cx = document.getElementById("listaGaleriaContainer");
        cx.innerHTML = "";
        galeriaState.forEach((item, index) => {
            cx.insertAdjacentHTML("beforeend", `
                <div style="display:flex; justify-content:space-between; align-items:center; background:#222; padding:8px; border:1px solid #444; border-radius:3px;">
                    <div style="font-size:11px; color:#aaa;">
                        <strong style="color:#F2B400;">${item.legenda}</strong><br>${item.url}
                    </div>
                    <button type="button" class="btn-del-img" data-index="${index}" style="background:var(--rus-vermelho); color:#fff; padding:4px 8px; border:none;">X</button>
                </div>
            `);
        });

        document.querySelectorAll(".btn-del-img").forEach(btn => {
            btn.onclick = (e) => {
                galeriaState.splice(parseInt(e.target.dataset.index), 1);
                renderizarEditorGaleria();
            };
        });
    };

    if (document.getElementById("btnAdicionarFoto")) {
        document.getElementById("btnAdicionarFoto").onclick = () => {
            const p = document.getElementById("novaFotoCaminho").value.trim();
            const l = document.getElementById("novaFotoLegenda").value.trim();
            if (p) {
                galeriaState.push({ url: p, legenda: l || "Visão Oficial em Combate" });
                document.getElementById("novaFotoCaminho").value = "";
                document.getElementById("novaFotoLegenda").value = "";
                renderizarEditorGaleria();
            }
        };
    }

    if (document.getElementById("formEdicaoTanque")) {
        document.getElementById("formEdicaoTanque").onsubmit = async (e) => {
            e.preventDefault();
            const btn = document.getElementById("btnSalvarDossie");
            btn.disabled = true;
            btn.innerHTML = "SALVANDO...";

            try {
                let form = new FormData();
                form.append("id", document.getElementById("editTankId").value);
                form.append("nome", document.getElementById("editNomePrincipal").value);
                form.append("descricao_breve", document.getElementById("editDescricaoBreve").value);
                form.append("caminho_imagem", document.getElementById("editCaminhoImagem").value);

                const getVal = (k) => { let i = specsState.find(x => x.chave === k); return i ? i.valor : ""; };

                form.append("armamento", getVal("Armamento Principal"));
                form.append("velocidade", getVal("Velocidade Máxima"));
                form.append("blindagem_chassi", getVal("Blindagem do Chassi"));
                form.append("blindagem_torre", getVal("Blindagem da Torre"));

                form.append("historico", document.getElementById("editHistorico").value);
                form.append("taticas", document.getElementById("editTaticas").value);
                form.append("detalhes_extras", JSON.stringify(specsState));
                form.append("galeria_imagens", JSON.stringify(galeriaState));
                form.append("classe_veiculo", document.getElementById("editClasse").value);
                form.append("tipo", document.getElementById("editFuncao").value);
                form.append("nivel", document.getElementById("editNivel").value);
                form.append("nacao_id", document.getElementById("editNacaoId").value);
                form.append("csrf_token", localStorage.getItem("csrf_token") || ""); // Passo 1.2

                const req = await fetch(`${basePath}php/api/atualizar_ficha.php`, { method: "POST", body: form });
                if (req.ok) window.location.reload();
            } catch (err) {
                btn.disabled = false;
                btn.innerHTML = "ERRO";
            }
        };
    }

    const btnDelete = document.getElementById("btnExcluirDossie");
    if (btnDelete) {
        btnDelete.onclick = async () => {
            if (confirm("ALERTA CRÍTICO: Tem certeza que deseja DELETAR o tanque?")) {
                btnDelete.disabled = true;
                btnDelete.innerHTML = "INCINERANDO...";
                try {
                    let form = new FormData();
                    form.append("id", document.getElementById("editTankId").value);
                    form.append("csrf_token", localStorage.getItem("csrf_token") || ""); // Passo 1.2
                    const req = await fetch(`${basePath}php/api/excluir_tanque.php`, { method: "POST", body: form });
                    if (req.ok) window.location.href = `${basePath}index.html`;
                } catch (err) {
                    btnDelete.disabled = false;
                    btnDelete.innerHTML = "ERRO";
                }
            }
        };
    }

    (async () => {
        try {
            const req = await fetch(`${basePath}php/api/ficha_api.php?id=${tId}`);
            const res = await req.json();

            if (res.status === "success") {
                const tk = res.dados;
                document.title = `${tk.nome} - Ficha Tática`;
                document.getElementById("dinNomeTanque").textContent = tk.nome;

                const cl = tk.classe_veiculo || "Médio";
                let badgeStr = prefixos[cl] || cl;
                if (tk.tipo && tk.tipo.trim() !== "") badgeStr += ` (${tk.tipo})`;
                badgeStr += ` | ${tk.nivel || "Nível ?"}`;

                const badgeEl = document.getElementById("dinTipoNivel");
                badgeEl.textContent = badgeStr;
                badgeEl.style.backgroundColor = corClasses[cl] || "#1A3668";
                badgeEl.style.color = (cl === "Leve") ? "#000000" : "#ffffff";

                document.getElementById("dinHistorico").innerHTML = tk.historico ? formatarTextoTatico(tk.historico) : "<p>Histórico classificado.</p>";
                document.getElementById("dinTaticas").innerHTML = tk.taticas ? formatarTextoTatico(tk.taticas) : "<p>Doutrina em formulação.</p>";

                const tbBody = document.getElementById("tabelaEspecificacoesBody");

                if (tk.detalhes_extras && tk.detalhes_extras !== "{}") {
                    try {
                        const parsed = JSON.parse(tk.detalhes_extras);
                        if (Array.isArray(parsed)) {
                            specsState = parsed;
                        } else {
                            specsState = Object.entries(parsed).map(([k, v]) => ({ chave: k, valor: v }));
                        }
                    } catch (e) { }
                }

                [
                    { chave: "Armamento Principal", valorDB: tk.armamento },
                    { chave: "Blindagem do Chassi", valorDB: tk.blindagem_chassi },
                    { chave: "Blindagem da Torre", valorDB: tk.blindagem_torre },
                    { chave: "Velocidade Máxima", valorDB: tk.velocidade }
                ].forEach(item => {
                    if (!specsState.some(s => s.chave === item.chave) && item.valorDB) {
                        specsState.push({ chave: item.chave, valor: item.valorDB });
                    }
                });

                tbBody.innerHTML = "";
                specsState.forEach(attr => {
                    if (attr.valor.trim() !== "") {
                        tbBody.insertAdjacentHTML("beforeend", `<tr><th>${attr.chave}</th><td>${attr.valor}</td></tr>`);
                    }
                });

                const track = document.getElementById("tank-track");
                const caption = document.getElementById("tank-caption");
                const btnPrev = document.getElementById("btnPrev");
                const btnNext = document.getElementById("btnNext");

                if (tk.galeria_imagens) {
                    try { galeriaState = JSON.parse(tk.galeria_imagens); } catch (e) { }
                }

                if (galeriaState.length > 0) {
                    track.innerHTML = "";
                    galeriaState.forEach(img => {
                        track.innerHTML += `<img src="${basePath}${img.url}?v=${new Date().getTime()}" alt="${img.legenda}" class="slide-item">`;
                    });
                    caption.textContent = galeriaState[0].legenda || "Visão Oficial em Combate";

                    if (galeriaState.length > 1) {
                        btnPrev.style.display = "block";
                        btnNext.style.display = "block";
                        let slideIndex = 0;

                        const updateSlide = () => {
                            track.style.transform = `translateX(-${slideIndex * 100}%)`;
                            caption.textContent = galeriaState[slideIndex].legenda || "";
                        };

                        btnNext.onclick = () => { slideIndex = (slideIndex + 1) % galeriaState.length; updateSlide(); };
                        btnPrev.onclick = () => { slideIndex = (slideIndex - 1 + galeriaState.length) % galeriaState.length; updateSlide(); };
                    }
                } else {
                    const pic = tk.caminho_imagem.replace("shadow.svg", "foto.webp").replace("shadow.png", "foto.webp");
                    document.getElementById("dinImagemPrincipal").src = `${basePath}${pic}?v=${new Date().getTime()}`;
                }

                if (loadOverlay) loadOverlay.style.display = "none";
                containerFicha.style.display = "block";

                if ((localStorage.getItem("userRole") || "").toLowerCase() === "admin" && btnAbrirEdicao) {
                    btnAbrirEdicao.style.display = "flex";
                    btnAbrirEdicao.onclick = async () => {
                        const selNacao = document.getElementById("editNacaoId");
                        if (selNacao) {
                            try {
                                selNacao.innerHTML = "<option value=''>Carregando Nações...</option>";
                                const rN = await fetch(`${basePath}php/api/listar_nacoes.php`);
                                const resN = await rN.json();
                                if (resN.status === "success") {
                                    selNacao.innerHTML = "";
                                    resN.nacoes.forEach(n => {
                                        selNacao.innerHTML += `<option value="${n.Id}">${n.nome}</option>`;
                                    });
                                }
                            } catch (e) {
                                console.error("Falha ao carregar nações.");
                            }
                        }

                        document.getElementById("editTankId").value = tk.id;
                        document.getElementById("editNomePrincipal").value = tk.nome || "";
                        document.getElementById("editDescricaoBreve").value = tk.descricao_breve || "";
                        document.getElementById("editCaminhoImagem").value = tk.caminho_imagem || "";
                        document.getElementById("editNomeTitulo").textContent = tk.nome;
                        document.getElementById("editHistorico").value = tk.historico || "";
                        document.getElementById("editTaticas").value = tk.taticas || "";
                        document.getElementById("editClasse").value = tk.classe_veiculo || "Médio";
                        document.getElementById("editFuncao").value = tk.tipo || "";
                        document.getElementById("editNivel").value = tk.nivel || "I";
                        if (selNacao) selNacao.value = tk.nacao_id || "1";

                        renderizarEditorAtributos();
                        renderizarEditorGaleria();
                        modalEdicao.classList.add("ativo");
                    };
                }
            }
        } catch (err) {
            if (loadOverlay) loadOverlay.innerHTML = "<span style='color:red;'>FALHA CRÍTICA DE CONEXÃO.</span>";
        }
    })();
}

function iniciarScrollSuave() {
    document.body.insertAdjacentHTML("beforeend", '<button id="btnVoltarTopo" title="Voltar ao Topo"><span class="texto-topo" style="color:#fff; font-weight:bold;">▲ TOPO</span></button>');
    let btn = document.getElementById("btnVoltarTopo");
    if (btn) {
        window.addEventListener("scroll", () => {
            btn.classList.toggle("visivel", window.scrollY > 300);
        });
        btn.addEventListener("click", () => document.body.scrollIntoView({ behavior: "smooth", block: "start" }));
    }
}

function iniciarToggleVisualizacao() {
    let btnToggle = document.getElementById("btnToggleView");
    let container = document.querySelector(".nation-content");
    if (btnToggle && container) {
        btnToggle.addEventListener("click", () => {
            container.classList.toggle("list-view");
            if (container.classList.contains("list-view")) {
                btnToggle.innerHTML = "&#9638; MODO CAIXAS";
            } else {
                btnToggle.innerHTML = "&#9776; MODO LISTA";
            }
        });
    }
}

function iniciarConfig() {
    let modalConfig = document.getElementById("configModal");
    let btnAbre = document.getElementById("btnOpenConfig");
    let btnFecha = document.getElementById("closeConfigModal");
    let tggPerf = document.getElementById("togglePerf");
    let selTema = document.getElementById("themeSelect");
    let selLang = document.getElementById("langSelect");
    let btnPurge = document.getElementById("btnPurge");

    if (!modalConfig || !btnAbre) return;

    btnAbre.addEventListener("click", e => {
        e.preventDefault();
        modalConfig.classList.add("ativo");
    });

    btnFecha.addEventListener("click", () => modalConfig.classList.remove("ativo"));

    if (localStorage.getItem("lowPerf") === "true") {
        tggPerf.checked = true;
        document.body.classList.add("low-perf");
    }

    tggPerf.addEventListener("change", e => {
        if (e.target.checked) {
            localStorage.setItem("lowPerf", "true");
            document.body.classList.add("low-perf");
        } else {
            localStorage.setItem("lowPerf", "false");
            document.body.classList.remove("low-perf");
        }
    });

    let temaAtual = localStorage.getItem("siteTheme") || "dark";
    selTema.value = temaAtual;
    if (temaAtual === "desert") document.body.classList.add("theme-desert");
    if (temaAtual === "night") document.body.classList.add("theme-night");

    selTema.addEventListener("change", e => {
        document.body.classList.remove("theme-desert", "theme-night");
        if (e.target.value === "desert") document.body.classList.add("theme-desert");
        if (e.target.value === "night") document.body.classList.add("theme-night");
        localStorage.setItem("siteTheme", e.target.value);
    });

    let langAtual = localStorage.getItem("siteLang") || "pt";
    selLang.value = langAtual;

    selLang.addEventListener("change", e => {
        localStorage.setItem("siteLang", e.target.value);
        let banner = document.getElementById("customBanner");
        if (banner) {
            document.getElementById("customBannerText").textContent = "Idioma salvo. Atualize a página.";
            document.getElementById("bannerIcon").innerHTML = "language";
            banner.classList.add("show");
            setTimeout(() => banner.classList.remove("show"), 4000);
        }
    });

    btnPurge.addEventListener("click", () => {
        localStorage.clear();
        location.reload();
    });
}

function injetarMenu(basePath) {
    document.addEventListener("DOMContentLoaded", () => {
        injetarInterface(basePath);
        iniciarLogin(basePath);
        iniciarRegistro(basePath);
        iniciarRecuperacaoSenha(basePath);
        iniciarConfig();
        iniciarRelogio();
        ativarRadarPesquisa(basePath);
        ativarAbaTatica();
        iniciarScrollSuave();
        iniciarToggleVisualizacao();
        iniciarTropas(basePath);
        iniciarIndex(basePath);
        iniciarNacao(basePath);
        iniciarFicha(basePath);
        iniciarPerfil(basePath);

        fetch(`${basePath}php/api/listar_nacoes.php`)
            .then(req => req.json())
            .then(res => {
                if (res.status === "success" && res.nacoes) {
                    const nacoes = res.nacoes;
                    const dropdown = document.getElementById("listaDinamicaNacoesDropdown");
                    const badge = document.getElementById("userNationBadge");

                    const atualizarBadge = (idNacao) => {
                        if (!badge) return;
                        const obj = nacoes.find(n => (n.id || n.Id) == idNacao) || nacoes[0];
                        if (!obj) return;
                        const sigla = obj.nome.substring(0, 3).toUpperCase();
                        const cor = obj.cor_hex || "#1d4ed8";

                        badge.style.borderColor = cor;
                        badge.style.boxShadow = `0 0 10px ${cor}80`;
                        badge.innerHTML = `
                            <div style="display:flex;align-items:center;gap:6px;">
                                <img src="${basePath}${obj.caminho_bandeira}" style="width:20px;height:14px;object-fit:cover;border-radius:2px;" onerror="this.style.display='none'">
                                <span style="font-weight:bold;color:#fff;font-size:11px;">${sigla}</span>
                            </div>
                            <span style="font-size:9px;color:#aaa;">${obj.nome.toUpperCase()}</span>
                            <span style="font-size:8px;color:#F2B400;margin-top:1px;">▼</span>
                        `;
                    };

                    const nacaoAtual = localStorage.getItem("userNation") || nacoes[0].id || nacoes[0].Id;
                    atualizarBadge(nacaoAtual);

                    if (dropdown) {
                        dropdown.innerHTML = "";
                        nacoes.forEach(t => {
                            const idLocal = t.id || t.Id;
                            const tSigla = t.nome.substring(0, 3).toUpperCase();
                            dropdown.innerHTML += `
                                <div class="nation-opt" data-nacao="${idLocal}" style="display:flex;align-items:center;gap:10px;padding:8px 12px;cursor:pointer;border-bottom:1px solid #222;font-size:11px;color:#fff;transition:0.2s;" onmouseover="this.style.background='#333'" onmouseout="this.style.background='transparent'">
                                    <img src="${basePath}${t.caminho_bandeira}" style="width:20px;height:14px;object-fit:cover;border-radius:2px;" onerror="this.style.display='none'">
                                    <span>${tSigla} – ${t.nome.toUpperCase()}</span>
                                </div>
                            `;
                        });

                        dropdown.querySelectorAll(".nation-opt").forEach(opt => {
                            opt.addEventListener("click", async n => {
                                n.stopPropagation();
                                const alvo = opt.getAttribute("data-nacao");
                                localStorage.setItem("userNation", alvo);
                                atualizarBadge(alvo);
                                document.getElementById("userNationDropdown").style.display = "none";

                                if (localStorage.getItem("isAuth") === "true") {
                                    try {
                                        let fd = new FormData();
                                        fd.append("acao", "salvar_nacao");
                                        fd.append("nacao", alvo);
                                        fd.append("csrf_token", localStorage.getItem("csrf_token") || ""); // Passo 1.2
                                        await fetch(`${basePath}php/api/usuarios.php`, { method: "POST", body: fd });
                                    } catch (err) {
                                        console.error("Falha ao salvar no banco:", err);
                                    }
                                }
                            });
                        });
                    }
                }
            })
            .catch(() => { });

        document.addEventListener("click", e => {
            let toggle = document.getElementById("navToggleBtn");
            let navbar = document.querySelector(".top-navbar");

            if (toggle && navbar) {
                if (toggle.contains(e.target)) {
                    navbar.classList.toggle("expanded");
                } else if (!navbar.contains(e.target)) {
                    navbar.classList.remove("expanded");
                }
            }

            const bNacao = document.getElementById("userNationBadge");
            const dNacao = document.getElementById("userNationDropdown");
            if (bNacao && dNacao) {
                if (bNacao.contains(e.target)) {
                    dNacao.style.display = dNacao.style.display === "block" ? "none" : "block";
                } else {
                    dNacao.style.display = "none";
                }
            }
        });
    });
}